/** Nivel 6 — ISR, IMSS e Infonavit. Lecciones 51–60. */
import type { Level, Lesson, LessonSection, QuizQuestion } from '@/domain/models/course.model';

// Solo se genera la estructura de identificación; cada lección tiene contenido propio.
type LessonContent = Omit<Lesson, 'id' | 'number' | 'sections' | 'quiz'> & {
  sections: Omit<LessonSection, 'id'>[];
  questions: Omit<QuizQuestion, 'id'>[];
};

function lesson(position: number, content: LessonContent): Lesson {
  const suffix = `06-${String(position).padStart(2, '0')}`;
  const { sections, questions, ...metadata } = content;
  return {
    ...metadata, id: `l${suffix}`, number: 50 + position,
    sections: sections.map((section, i) => ({ ...section, id: `l${suffix}-s${i + 1}` })),
    quiz: {
      id: `q${suffix}`, title: `Mini examen — Lección ${50 + position}`,
      description: `Comprueba lo aprendido: ${content.title}.`, passingScore: 70,
      questions: questions.map((question, i) => ({ ...question, id: `q${suffix}-${i + 1}` })),
    },
  };
}

